<script lang="ts">export interface AccordionItem{title:string;content:string;disabled?:boolean}let{items,multiple=false}:{items:AccordionItem[];multiple?:boolean}=$props();let expanded=$state<number[]>([]);function toggle(i:number){expanded=expanded.includes(i)?expanded.filter(x=>x!==i):multiple?[...expanded,i]:[i];}</script>
<div class="ds-accordion">{#each items as item,i}<section><h3><button class="ds-focus" aria-expanded={expanded.includes(i)} disabled={item.disabled} onclick={()=>toggle(i)}>{item.title}<span>{expanded.includes(i)?'−':'+'}</span></button></h3>{#if expanded.includes(i)}<div class="panel">{item.content}</div>{/if}</section>{/each}</div>
<style>.ds-accordion{border-top:1px solid var(--ds-border)}section{border-bottom:1px solid var(--ds-border)}h3{margin:0}button{display:flex;justify-content:space-between;width:100%;padding:1rem 0;border:0;background:transparent;color:var(--ds-text);text-align:left;font:600 .9375rem var(--ds-font);cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}.panel{padding:0 0 1rem;color:var(--ds-muted);font-size:.875rem;line-height:1.6}</style>